actions.script:
const words = {Firing: 'Firing', Normal: 'Normal', Pending: 'Pending', Recovering: 'Recovering', NoData: 'No data (not known)', Error: 'Error (not known)'}
alertLink = link ? String(link) : ''
if (alertLink.startsWith('/') && typeof webHostName !== 'undefined' && webHostName)
    alertLink = 'https://' + String(webHostName).replace(/^https?:\/\//, '').replace(/\/$/, '') + alertLink
alertLines = Array.from(events || []).slice(0, 50).map(event => {
    const labels = Object.entries(event.labels || {}).filter(([name]) => name !== 'field' && name !== 'rule')
        .map(([name, value]) => name + ' ' + value).join(', ')
    const state = Object.hasOwn(words, String(event.state)) ? words[String(event.state)] : 'Not known'
    const reading = event.value == null || event.state === 'NoData' || event.state === 'Error' ? '' : ': ' + Math.round(Number(String(event.value)) * 100) / 100
    return (labels ? labels + ' — ' : '') + state + reading
})

render-mode.text:
${title}
<#list alertLines as line>${line}
</#list>${alertLink}
This was sent to you alone, as you may read what its owner reads.
